package com.zhineng.platform.evaluation.selfevaluation.repository;
import java.sql.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.support.*;import org.springframework.stereotype.Repository;
@Repository public class SelfEvaluationRepository{
 private final JdbcTemplate jdbc;public SelfEvaluationRepository(JdbcTemplate j){jdbc=j;}
 public List<Map<String,Object>>versions(){return jdbc.queryForList("SELECT v.id,v.version_name,v.evaluation_year,s.system_name,count(i.id) item_count FROM indicator_versions v JOIN indicator_systems s ON s.id=v.system_id LEFT JOIN indicator_items i ON i.version_id=v.id AND i.indicator_level=3 AND i.status='ACTIVE' WHERE v.status='PUBLISHED' GROUP BY v.id ORDER BY v.evaluation_year DESC,v.id DESC");}
 public Map<String,Object>version(long id){return one("SELECT * FROM indicator_versions WHERE id=? AND status='PUBLISHED'",id);}
 public List<Map<String,Object>>orgs(){return jdbc.queryForList("SELECT id,unit_code,unit_name FROM org_units WHERE status='ACTIVE' AND unit_type NOT IN('ROOT','GROUP') ORDER BY sort_order,id");}
 public Map<String,Object>org(long id){return one("SELECT * FROM org_units WHERE id=? AND status='ACTIVE' AND unit_type NOT IN('ROOT','GROUP')",id);}
 public List<Map<String,Object>>tasks(){return jdbc.queryForList("SELECT t.*,v.version_name,count(o.id) org_count,sum(CASE WHEN o.status='COMPLETED' THEN 1 ELSE 0 END) completed_orgs,round(CASE WHEN count(o.id)=0 THEN 0 ELSE 100.0*sum(CASE WHEN o.status IN('SUBMITTED','COMPLETED') THEN 1 ELSE 0 END)/count(o.id) END,1) progress FROM self_evaluation_tasks t JOIN indicator_versions v ON v.id=t.indicator_version_id LEFT JOIN self_evaluation_task_orgs o ON o.task_id=t.id GROUP BY t.id ORDER BY t.evaluation_year DESC,t.id DESC");}
 public Map<String,Object>task(long id){return one("SELECT t.*,v.version_name,v.status indicator_status,s.system_name FROM self_evaluation_tasks t JOIN indicator_versions v ON v.id=t.indicator_version_id JOIN indicator_systems s ON s.id=v.system_id WHERE t.id=?",id);}
 public List<Map<String,Object>>taskOrgs(long id){return jdbc.queryForList("SELECT x.*,o.unit_code,o.unit_name FROM self_evaluation_task_orgs x JOIN org_units o ON o.id=x.org_unit_id WHERE x.task_id=? ORDER BY o.sort_order,o.id",id);}
 public long addTask(String code,String name,int year,String type,String start,String end,String desc,long version,long uid){return insert("INSERT INTO self_evaluation_tasks(task_code,task_name,evaluation_year,task_type,start_date,end_date,description,indicator_version_id,created_by,updated_by)VALUES(?,?,?,?,?,?,?,?,?,?)",code,name,year,type,start,end,desc,version,uid,uid);}
 public long addTaskOrg(long task,long org){return insert("INSERT INTO self_evaluation_task_orgs(task_id,org_unit_id)VALUES(?,?)",task,org);}
 public List<Map<String,Object>>sourceIndicators(long version){return jdbc.queryForList("SELECT * FROM indicator_items WHERE version_id=? AND indicator_level=3 AND status='ACTIVE' ORDER BY sort_order,id",version);}
 public long addSnapshot(long task,Map<String,Object>i,String due){return insert("INSERT INTO self_evaluation_indicator_snapshots(task_id,source_indicator_id,indicator_code,indicator_name,standard_score,weight,due_date,sort_order)VALUES(?,?,?,?,?,?,?,?)",task,i.get("id"),i.get("indicator_code"),i.get("indicator_name"),i.get("standard_score"),i.get("weight"),due,i.get("sort_order"));}
 public void addEntry(long org,long snapshot,long uid){jdbc.update("INSERT INTO self_evaluation_entries(task_org_id,snapshot_id,updated_by)VALUES(?,?,?)",org,snapshot,uid);}
 public int publish(long id,long uid){return jdbc.update("UPDATE self_evaluation_tasks SET status='PUBLISHED',published_by=?,published_at=strftime('%Y-%m-%dT%H:%M:%SZ','now'),updated_by=?,updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE id=? AND status='DRAFT'",uid,uid,id);}
 public int cancelTask(long id,long uid){return jdbc.update("UPDATE self_evaluation_tasks SET status='CANCELLED',updated_by=?,updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE id=? AND status NOT IN('COMPLETED','CANCELLED')",uid,id);}
 public void syncTaskStatus(long task){jdbc.update("UPDATE self_evaluation_tasks SET status=CASE WHEN (SELECT count(*) FROM self_evaluation_task_orgs WHERE task_id=? AND status<>'COMPLETED')=0 THEN 'COMPLETED' WHEN EXISTS(SELECT 1 FROM self_evaluation_task_orgs WHERE task_id=? AND status='RETURNED') THEN 'RETURNED' WHEN (SELECT count(*) FROM self_evaluation_task_orgs WHERE task_id=? AND status NOT IN('SUBMITTED','COMPLETED'))=0 THEN 'SUBMITTED' WHEN EXISTS(SELECT 1 FROM self_evaluation_task_orgs WHERE task_id=? AND status='DRAFT') THEN 'FILLING' ELSE status END WHERE id=? AND status<>'CANCELLED'",task,task,task,task,task);}
 public void taskHistory(long id,String from,String to,String op,long uid){jdbc.update("INSERT INTO self_evaluation_status_history(business_type,business_id,from_status,to_status,opinion,operator_id)VALUES('TASK',?,?,?,?,?)",id,from,to,op,uid);}
 public void orgHistory(long id,String from,String to,String op,long uid){jdbc.update("INSERT INTO self_evaluation_status_history(business_type,business_id,from_status,to_status,opinion,operator_id)VALUES('TASK_ORG',?,?,?,?,?)",id,from,to,op,uid);}
 public Map<String,Object>taskOrg(long id){return one("SELECT x.*,o.unit_name,t.task_name,t.status task_status,t.end_date FROM self_evaluation_task_orgs x JOIN org_units o ON o.id=x.org_unit_id JOIN self_evaluation_tasks t ON t.id=x.task_id WHERE x.id=?",id);}
 public List<Map<String,Object>>entries(long org){return jdbc.queryForList("SELECT e.*,s.indicator_code,s.indicator_name,s.standard_score,s.weight,s.required_material_count,s.allowed_extensions,s.naming_keywords,s.due_date,(SELECT count(*) FROM self_evaluation_materials m WHERE m.entry_id=e.id AND m.status='ACTIVE' AND m.is_current=1) material_count FROM self_evaluation_entries e JOIN self_evaluation_indicator_snapshots s ON s.id=e.snapshot_id WHERE e.task_org_id=? ORDER BY s.sort_order,s.id",org);}
 public Map<String,Object>entry(long id){return one("SELECT e.*,s.*,x.status org_status,x.org_unit_id,x.task_id FROM self_evaluation_entries e JOIN self_evaluation_indicator_snapshots s ON s.id=e.snapshot_id JOIN self_evaluation_task_orgs x ON x.id=e.task_org_id WHERE e.id=?",id);}
 public int saveEntry(long id,Double score,String desc,String completion,int rv,long uid){return jdbc.update("UPDATE self_evaluation_entries SET self_score=?,performance_description=?,completion_status=?,updated_by=?,updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now'),row_version=row_version+1 WHERE id=? AND row_version=?",score,desc,completion,uid,id,rv);}
 public void recalc(long org){jdbc.update("UPDATE self_evaluation_task_orgs SET total_score=(SELECT COALESCE(sum(self_score),0) FROM self_evaluation_entries WHERE task_org_id=?),completed_items=(SELECT count(*) FROM self_evaluation_entries WHERE task_org_id=? AND self_score IS NOT NULL AND performance_description IS NOT NULL AND trim(performance_description)<>''),total_items=(SELECT count(*) FROM self_evaluation_entries WHERE task_org_id=?),status=CASE WHEN status='NOT_STARTED' THEN 'DRAFT' ELSE status END,updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE id=?",org,org,org,org);}
 public int orgStatus(long id,String from,String to,String opinion,long uid){String extra="SUBMITTED".equals(to)?",submitted_by="+uid+",submitted_at=strftime('%Y-%m-%dT%H:%M:%SZ','now')":("COMPLETED".equals(to)||"RETURNED".equals(to))?",reviewed_by="+uid+",reviewed_at=strftime('%Y-%m-%dT%H:%M:%SZ','now'),review_opinion=?":"";if(extra.contains("?"))return jdbc.update("UPDATE self_evaluation_task_orgs SET status=?"+extra+" WHERE id=? AND status=?",to,opinion,id,from);return jdbc.update("UPDATE self_evaluation_task_orgs SET status=?"+extra+" WHERE id=? AND status=?",to,id,from);}
 public int requirement(long id,int count,String ext,String keywords,String due){return jdbc.update("UPDATE self_evaluation_indicator_snapshots SET required_material_count=?,allowed_extensions=?,naming_keywords=?,due_date=? WHERE id=?",count,ext,keywords,due,id);}
 public long addAttachment(long entry,String original,String stored,String path,String type,String ext,long size,long uid){return insert("INSERT INTO sys_attachments(business_type,business_id,original_name,stored_name,storage_path,content_type,extension,file_size,uploaded_by)VALUES('SELF_EVALUATION_ENTRY',?,?,?,?,?,?,?,?)",entry,original,stored,path,type,ext,size,uid);}
 public Map<String,Object>latestMaterial(String group){return one("SELECT * FROM self_evaluation_materials WHERE version_group=? AND status='ACTIVE' AND is_current=1",group);}
 public long addMaterial(long entry,long attachment,String group,int ver,String name,String category,String desc,String source,String classStatus,String documentDate,long uid){return insert("INSERT INTO self_evaluation_materials(entry_id,attachment_id,version_group,version_no,material_name,category,description,classification_source,classification_status,document_date,uploaded_by)VALUES(?,?,?,?,?,?,?,?,?,?,?)",entry,attachment,group,ver,name,category,desc,source,classStatus,documentDate,uid);}
 public void retireMaterial(long id){jdbc.update("UPDATE self_evaluation_materials SET is_current=0 WHERE id=?",id);}
 public int materialStatus(long id,String status){return jdbc.update("UPDATE self_evaluation_materials SET status=?,is_current=CASE WHEN ?='INACTIVE' THEN 0 ELSE is_current END WHERE id=?",status,status,id);}
 public int confirmMaterial(long id,String category){return jdbc.update("UPDATE self_evaluation_materials SET category=?,classification_status='CONFIRMED',classification_source='MANUAL' WHERE id=?",category,id);}
 public List<Map<String,Object>>materials(long entry){return jdbc.queryForList("SELECT m.*,a.original_name,a.content_type,a.extension,a.file_size FROM self_evaluation_materials m JOIN sys_attachments a ON a.id=m.attachment_id WHERE m.entry_id=? ORDER BY m.version_group,m.version_no DESC",entry);}
 public Map<String,Object>attachment(long id){return one("SELECT a.* FROM sys_attachments a JOIN self_evaluation_materials m ON m.attachment_id=a.id WHERE a.id=? AND a.status='ACTIVE'",id);}
 public long addRun(long task,Long org,long uid){return insert("INSERT INTO self_evaluation_warning_runs(task_id,org_unit_id,created_by)VALUES(?,?,?)",task,org,uid);}
 public void addWarning(long run,long org,long snap,String type,String msg){jdbc.update("INSERT INTO self_evaluation_warnings(run_id,task_org_id,snapshot_id,warning_type,message)VALUES(?,?,?,?,?)",run,org,snap,type,msg);}
 public void finishRun(long run,int checks,int warnings){jdbc.update("UPDATE self_evaluation_warning_runs SET total_checks=?,warning_count=? WHERE id=?",checks,warnings,run);}
 public List<Map<String,Object>>warningCandidates(long task,Long org){String f=org==null?"":" AND x.org_unit_id="+org;return jdbc.queryForList("SELECT x.id task_org_id,x.org_unit_id,o.unit_name,e.id entry_id,s.*,t.start_date FROM self_evaluation_task_orgs x JOIN self_evaluation_tasks t ON t.id=x.task_id JOIN org_units o ON o.id=x.org_unit_id JOIN self_evaluation_entries e ON e.task_org_id=x.id JOIN self_evaluation_indicator_snapshots s ON s.id=e.snapshot_id WHERE x.task_id=?"+f+" ORDER BY x.id,s.sort_order",task);}
 public List<Map<String,Object>>warnings(Long run){String f=run==null?"":" WHERE w.run_id="+run;return jdbc.queryForList("SELECT w.*,o.unit_name,s.indicator_code,s.indicator_name,r.created_at run_at FROM self_evaluation_warnings w JOIN self_evaluation_warning_runs r ON r.id=w.run_id JOIN self_evaluation_task_orgs x ON x.id=w.task_org_id JOIN org_units o ON o.id=x.org_unit_id JOIN self_evaluation_indicator_snapshots s ON s.id=w.snapshot_id"+f+" ORDER BY w.id DESC");}
 public Map<String,Object>warning(long id){return one("SELECT * FROM self_evaluation_warnings WHERE id=?",id);}
 public int processWarning(long id,String status,String op,long uid){return jdbc.update("UPDATE self_evaluation_warnings SET status=?,process_opinion=?,processed_by=?,processed_at=strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE id=?",status,op,uid,id);}
 public void remind(long id,String recipient,String content,long uid){jdbc.update("INSERT INTO self_evaluation_reminder_logs(warning_id,recipient,content,sent_by)VALUES(?,?,?,?)",id,recipient,content,uid);}
 public List<Map<String,Object>>reminders(){return jdbc.queryForList("SELECT r.*,w.message FROM self_evaluation_reminder_logs r JOIN self_evaluation_warnings w ON w.id=r.warning_id ORDER BY r.id DESC");}
 public Map<String,Object>one(String sql,Object...p){List<Map<String,Object>>r=jdbc.queryForList(sql,p);return r.isEmpty()?null:r.get(0);}private long insert(String sql,Object...a){KeyHolder k=new GeneratedKeyHolder();jdbc.update(c->{PreparedStatement s=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS);for(int i=0;i<a.length;i++)s.setObject(i+1,a[i]);return s;},k);return k.getKey().longValue();}
}
